import request from '@/utils/request'
// import qs from 'qs'
import axios from 'axios'

// 登录方法，不需要验证码
export function authtoken(loginForm) {
  const data = {
    ...loginForm
  };
  return request({
    url: "/hsop/auth/token",
    method: "post",
    data: data
  });
}


export function getValidCode(query) {
  return request({
    url: '/hsop/auth/queryYanzhengMa',
    method: 'get',
    responseType: 'blob',
    params: query
  })
}

export function login(data) {
  return request({
    url: '/hsop/auth/login',
    method: 'post',
    // headers: { 'content-type': 'application/x-www-form-urlencoded' },
    // data: qs.stringify(data)
    data
  })
}

export function getInfo() {
  return request({
    url: '/hsop/userRole',
    method: 'get'
    // headers: { 'content-type': 'application/x-www-form-urlencoded' },
    // params: { token }
  })
}

export function logout() {
  return request({
    url: '/hsop/auth/removeToken',
    method: 'post'
  })
}

