<template>
  <div class="login">
    <!-- <div class="img_section">
      <img src="@/assets/login/background-login.png" alt="欢迎来到HSOP系统" class="login_background">
      <img src="@/assets/login/logo-login.png" alt="HSOP" class="login_logo">
    </div> -->
    <div class="login_section">
      <h1 class="welcome_title">欢迎登录舌诊系统</h1>
      <div class="login_tab_container">
        <div class="login_form_container">
          <el-form :model="loginForm" :rules="loginRules" class="login_form" ref="login-form">
            <el-form-item prop="loginName">
              <el-input class="qinghua-input" auto-complete="off" placeholder="请输入用户名" v-model="loginForm.loginName">
                <!-- <i class="el-icon-user-solid"></i> -->
                <img slot="prefix" :src="require('@/assets/login/user.png')" alt="">
              </el-input>
            </el-form-item>
            <el-form-item prop="password">
              <el-input class="qinghua-input" type="password" auto-complete="off" placeholder="请输入密码" v-model="loginForm.password">
                <!-- <i slot="prefix" class="el-icon-lock-solid"></i> -->
                <img slot="prefix" :src="require('@/assets/login/lock.png')" alt="">
              </el-input>
            </el-form-item>
            <!-- <el-form-item class="remember_row">
              <el-checkbox v-model="willRemember">记住密码</el-checkbox>
              <a href="#" class="link_forgot">忘记密码 ？</a>
            </el-form-item> -->
            <el-form-item class="form_action_row">
              <div type="primary" @click="handleLogin('login-form')" class="button_login">登录</div>
            </el-form-item>
          </el-form>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import sm from '@/utils/ses-crypto-ui'
const sm4 = new sm().sm4

export default {
  name: 'Login',
  data() {
    const validatePassword = (rule, value, callback) => {
      if (value === '') {
        callback(new Error('请输入密码'));
      } else {
        if (this.logupForm.passwordAgain !== '') {
          this.$refs['logup-form'].validateField('passwordAgain');
        }
        callback();
      }
    };
    const validatePasswordAgain = (rule, value, callback) => {
      if (value === '') {
        callback(new Error('请再次输入密码'));
      } else if (value !== this.logupForm.password) {
        callback(new Error('两次输入密码不一致!'));
      } else {
        callback();
      }
    };

    return {
      loginForm: {
        loginName: '',
        password: '',
      },
      loginRules: {
        loginName: [
          {
            required: true,
            message: '请输入用户名',
            trigger: 'blur',
          },
        ],
        password: [
          {
            required: true,
            message: '请输入密码',
            trigger: 'blur',
          },
        ],
      },
      willRemember: false,
      logupForm: {
        username: '',
        password: '',
        passwordAgain: '',
      },
      logupRules: {
        username: [
          {
            required: true,
            message: '请输入用户名',
            trigger: 'blur',
          },
        ],
        password: [
          {
            validator: validatePassword,
            trigger: 'blur',
          },
        ],
        passwordAgain: [
          {
            validator: validatePasswordAgain,
            trigger: 'blur',
          },
        ],
      },
    }
  },
  methods: {
    login(formRefName) {
      this.$refs[formRefName].validate(async (valid) => {
        if (valid) {
          // let resSm4 = await this.$apiServe.getSm4(this.loginForm.password)
          const data = {
            // username: 'ASP0000_1',
            // username: 'admin',
            username: this.loginForm.username,
            // password: 'JPFWJ68Wbz9uA7wgcUK1sQ=='
            password: sm4.encrypt(this.loginForm.password, '77730e71d5f76619')
            // password: resSm4.result
          }
          this.$apiServe.login(data).then(res => {
            this.$store.commit('SET_TOKEN', res.access_token)
            this.$store.commit('SET_REFRESH_TOKEN', res.refresh_token)
            this.$router.replace('/review')

            this.$refreshToken = setTimeout(() => {
              this.refreshToken()
            }, res.expires_in * 1000 - 100000)
          })
        } else {
          console.log('something wrong...');
          return false;
        }
        // if (this.loginForm.username === 'admin' && this.loginForm.password === '123456') {
        //   this.$router.replace('/data-all')
        // } else {
        //   this.$message.error('账号或密码错误！')
        // }
      });
    },
    refreshToken() {
      const data = {
        refresh_token: this.$store.state.refreshToken,
        scope: 'server'
      }
      this.$apiServe.refreshToken(data).then(res => {
        this.$store.commit('SET_TOKEN', res.access_token)
        this.$store.commit('SET_REFRESH_TOKEN', res.refresh_token)

        this.$refreshToken = setTimeout(() => {
          this.refreshToken()
        }, 100)
      })
    },
    logup(formRefName) {
      this.$refs[formRefName].validate((valid) => {
        if (valid) {
          this.$store.commit('UPDATE_LOGIN_STATUS', true)
          this.$router.replace('/')
        } else {
          console.log('something wrong...');
          return false;
        }
      });
    },
    handleLogin(form) {
      this.$refs[form].validate((valid) => {
        if (valid) {
          this.loading = true
          this.$store
            .dispatch('user/Authorize', this.loginForm)
            // .dispatch('user/Authorize', { password: '123456', loginName: '15184461234' })
            .then((res) => {
              this.$router.push({
                // path: this.$route.name === 'referralLogin'? res.identity === 2 ? '/auditor': '/doctor':'/home',
                path: '/review',
                query: this.otherQuery,
              })
              this.loading = false
            })
            .catch(() => {
              this.loading = false
            })
        } else {
          console.log('error submit!!')
          return false
        }
      })
    },
  },
}
</script>

<style lang="less">
.login {
  display: flex;
  width: 100vw;
  height: 100vh;
  justify-content: center;
  align-items: center;
  background: url('../assets/login/background-login.png') no-repeat;
  background-size: 100% 100%;

  .img_section {
    flex: 0 1 58%;
    position: relative;
    margin-right: 96px;
    padding-top: 76px;
    height: 100%;
  }

  .login_background {
    width: 100%;
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
  }

  .login_logo {
    width: 120px;
    position: absolute;
    left: 0;
    top: 0;
  }

  .login_section {
    flex: 0 0 360px;
    display: flex;
    flex-direction: column;
  }

  .welcome_title {
    width: 120%;
    margin: 0 0 45px -10%;
    font-family: Songti SC, Songti SC;
    font-weight: 900;
    font-size: 36px;
    color: #01499D;
    text-align: center;
  }

  .el-checkbox {
    color: #565656;
  }
}

.remember_row {

  .el-form-item__content {
    display: flex;
    justify-content: space-between;

    &:before,
    &:after {
      display: none;
    }
  }
}

.link_forgot {
  color: #446FF6;
}

.button_login {
  width: 100%;
  height: 52px;
  line-height: 52px;
  text-align: center;
  color: #FFF;
  background: url('../assets/login/login-btn.png') no-repeat;
  background-size: 100% 100%;
  cursor: pointer;
}
.button_logup {
  width: 100%;
}
.qinghua-input {
  // >.el-input__inner {
  background: url('../assets/login/qinghua-input.png') no-repeat;
  background-size: 100% 100%;
  border: none;
  width: 425px;
  // }
  >.el-input__inner {
    background: none;
    border: none;
    height: 52px;
    line-height: 52px;
    padding-left: 60px;
  }
  >.el-input__prefix {
    display: flex;
    align-items: center;
    margin-left: 24px;
    img {
      width: 20px;
      height: 20px;
    }
  }
}
</style>
