import { queryRolePage } from '@/service/roles'

const state = {
  roleList: []
}

const mutations = {
  SET_ROLELIST: (state, roleList) => {
    state.roleList = roleList
  }
}

const actions = {
  // roleList
  queryRolePage({ commit }, roleList) {
    return new Promise((resolve, reject) => {
      queryRolePage(roleList)
        .then(response => {
          console.log(response)
          commit('SET_ROLELIST', roleList)
          resolve()
        })
        .catch(error => {
          reject(error)
        })
    })
  }
}

export default {
  namespaced: true,
  state,
  mutations,
  actions
}
