<template>
  <div class="breadcrumb">
    <el-breadcrumb separator="/">
      <el-breadcrumb-item :to="idx === 0 ? undefined:{ path: item.path }" v-for="(item, idx) in matched" :key="item.name">{{ item.meta.title }}</el-breadcrumb-item>
    </el-breadcrumb>
  </div>
</template>

<script>
export default {
  data() {
    return {
      matched: []
    }
  },
  created() {
    // this.matched = JSON.parse(JSON.stringify(this.$route.matched))
    // this.matched = this.$route.matched

    this.matched = []
    this.$route.matched.map((item, idx) => {
      if (idx !== 0) {
        this.matched.push(item)
      }
    })
  },
  watch: {
    '$route.matched': {
      handler() {
        this.matched = []
        this.$route.matched.map((item, idx) => {
          if (idx !== 0) {
            this.matched.push(item)
          }
        })
      }
    }
  },
  methods: {
  }
}
</script>

<style lang="less" scope>
.breadcrumb {
  width: 100%;
  padding: 16px 24px;
  background: #FFF;
  // .el-breadcrumb {
  //   line-height: 24px;
  // }
}
</style>
