  <div class="dashboard">
    <el-container class="dashboard_container">
      <el-header height="80px" class="header">
        <Logo/>
        <div class="header_end">
          <HeaderPerson></HeaderPerson>
        </div>
      </el-header>
      <el-container class="main_container">
        <el-aside class="side" width="132px">
          <!-- <AsideMenu @refresh="key++"/> -->
          <Menu></Menu>
        </el-aside>
        <el-main class="main">
          <el-tabs class="act-menu" v-model="editableTabsValue" type="card" :closable="editableTabs.length>1" @tab-remove="removeTab" @tab-click="changeTab">
            <el-tab-pane
              v-for="(item, index) in editableTabs"
              :key="item.id"
              :label="item.title"
              :name="item.id"
            >
            </el-tab-pane>
          </el-tabs>
          <!-- <keep-alive :exclude="['ShezhenAdminDetail']"> -->
          <keep-alive>
            <router-view class="router-view" :key="$route.path + getArrItemNum(rmPath, $route.path)"></router-view>
          </keep-alive>
        </el-main>
      </el-container>
    </el-container>
  </div>
</template>

<script>
import Logo from '@/components/aside/Logo.vue'
import Timer from '@/components/aside/Timer.vue'
import Menu from '@/components/aside/Menu.vue'
import HeaderPerson from '@/components/header/HeaderPerson.vue'
import HeaderFunction from '@/components/header/HeaderFunction.vue'
import Breadcrumb from '@/components/common/Breadcrumb.vue'

export default {
  name: 'Dashboard',
  components: {
    Logo,
    Timer,
    Menu,
    HeaderPerson,
    HeaderFunction,
    Breadcrumb
  },
  data() {
    return {
      editableTabsValue: '所有API',
      editableTabs: [],
      rmPath: []
    }
  },
  computed: {
  },
  watch: {
    '$route.path'(newVal, oldVal) {
      this.addTab(newVal)
    },
  },
  created() {
    this.addTab(this.$route.path)
  },
  methods: {
    getArrItemNum(arr, key) {
      console.log(123)
      let mapObj = new Map();
      arr.forEach(element => {
        let num = mapObj.get(element);
        if (num) {
          mapObj.set(element, ++num);
        } else {
          mapObj.set(element, 1);
        }
      });
      return Object.fromEntries(mapObj.entries())[key];
    },
    addTab(path) {
      this.editableTabsValue = path
      if (this.editableTabs.find(item => item.id === path)) {
        return this.editableTabs.find(item => item.id === path).title = this.$route.params.title || this.$route.meta.title || '详情'
      }
      // this.$nextTick(() => {
      this.editableTabs.push({
        id: path,
        title: this.$route.params.title || this.$route.meta.title || '详情'
      })
      // })
    },
    removeTab(targetName) {
      let tabs = this.editableTabs;
      let activeName = this.editableTabsValue;
      if (activeName === targetName) {
        tabs.forEach((tab, index) => {
          if (tab.id === targetName) {
            let nextTab = tabs[index + 1] || tabs[index - 1];
            if (nextTab) {
              activeName = nextTab.id;
            }
          }
        });
      }
      this.editableTabsValue = activeName;
      this.$router.push(activeName)
      this.editableTabs = tabs.filter(tab => tab.id !== targetName);

      this.rmPath.push(targetName)
    },
    changeTab(tab) {
      this.$router.push(tab.name)
    }
  }
}
</script>

