import { login, logout, getInfo, authtoken, getPlaToken } from '@/service/login'
import { getToken, setToken, removeToken } from '@/utils/auth'
import router, { resetRouter } from '@/router'
import SesCrypto from 'ses-crypto-ui'
import { key } from '@/utils/sm4'
const sesCrypto = new SesCrypto()
// const key = 'boajexumikm7zemg'

// import { asyncRoutes, constantRoutes } from '@/router'
const state = {
  token: getToken(),
  name: '',
  avatar: '',
  menuActionInfo: '',
  roles: [],
  roleCode: '',
  roleName: '',
  roleAuth: '',

  hsopUser: {},
  plaToken: ''
}

const mutations = {
  SET_TOKEN: (state, token) => {
    state.token = token
  },
  SET_MENUINFO: (state, menuActionInfo) => {
    state.menuActionInfo = menuActionInfo
  },
  SET_ROLECODE: (state, roleCode) => {
    state.roleCode = roleCode
  },
  SET_NAME: (state, name) => {
    state.name = name
  },
  SET_AVATAR: (state, avatar) => {
    state.avatar = avatar
  },
  SET_ROLES: (state, roles) => {
    state.roles = roles
  },
  SET_ROLENAME: (state, roleName) => {
    state.roleName = roleName
  },
  SET_ROLEAUTH: (state, roleAuth) => {
    state.roleAuth = roleAuth
  },

  SET_HSOPUSER: (state, hsopUser) => {
    state.hsopUser = hsopUser
  },
  SET_UPLOADTOKEN: (state, plaToken) => {
    state.plaToken = plaToken
  },
}

const actions = {
  // 登录
  Authorize({ commit }, user) {
    const userInfo = JSON.parse(JSON.stringify(user))
    // const loginName = userInfo.loginName
    // const password = sesCrypto.sm4.encrypt(userInfo.password, key)
    userInfo.password = sesCrypto.sm4.encrypt(userInfo.password, key)
    // const enc = userInfo.enc
    return new Promise((resolve, reject) => {
      authtoken(userInfo)
        .then(res => {
          const token = 'Bearer ' + res.token
          setToken(token)
          commit('SET_TOKEN', token)
          commit('SET_HSOPUSER', res.hsopUser)
          console.log('res.hsopUser', res.hsopUser)
          resolve(res.hsopUser)
        })
        .catch(error => {
          reject(error)
        })
    })
  },

  // user login
  login({ commit }, userInfo) {
    // const { username, password } = userInfo
    return new Promise((resolve, reject) => {
      //   login({ username: username.trim(), password: password }).then(response => {
      login(userInfo)
        .then(response => {
          // const { result } = response
          console.log(response)
          const token = 'Bearer ' + response.token
          commit('SET_TOKEN', token)
          setToken(token)
          getPlaToken().then(res => {
            // this.plaToken = res.data.access_token
            commit('SET_UPLOADTOKEN', res.data.access_token)
            return res
          })
          resolve()
        })
        .catch(error => {
          reject(error)
        })
    })
  },

  // get user info
  getInfo({ commit, state }) {
    return new Promise((resolve, reject) => {
      getInfo()
        .then(response => {
          console.log(response)
          // const {data} = response
          // const data = response.result
          if (!response) {
            reject('Verification failed, please Login again.')
          }

          // const { roles, name, avatar, introduction } = data
          const {
            roleId,
            roleName,
            userName,
            menuActionInfo,
            roleCode
          } = response
          // roles must be a non-empty array
          const roles = [].concat(roleId)
          const roleAuth = menuActionInfo.roles
          if (!roleId || roles.length <= 0) {
            reject('getInfo: roles must be a non-null array!')
          }

          commit('SET_ROLES', roles)
          commit('SET_NAME', userName)
          commit('SET_ROLENAME', roleName)
          commit('SET_MENUINFO', menuActionInfo)
          commit('SET_ROLECODE', roleCode)
          commit('SET_ROLEAUTH', roleAuth)
          resolve(response)
        })
        .catch(error => {
          console.log(90909, error)
          reject(error)
        })
    })
  },

  // user logout
  logout({ commit, state, dispatch }) {
    return new Promise((resolve, reject) => {
      logout()
        .then(() => {
          commit('SET_TOKEN', '')
          commit('SET_ROLES', [])
          removeToken()
          resetRouter()

          // reset visited views and cached views
          // to fixed https://github.com/PanJiaChen/vue-element-admin/issues/2485
          // dispatch('tagsView/delAllViews', null, { root: true })

          resolve()
        })
        .catch(error => {
          reject(error)
        })
    })
  },

  // remove token
  resetToken({ commit }) {
    return new Promise(resolve => {
      commit('SET_TOKEN', '')
      commit('SET_ROLES', [])
      removeToken()
      resolve()
    })
  },

  // dynamically modify permissions
  changeRoles({ commit, dispatch }, role) {
    return new Promise(async resolve => {
      const token = role + '-token'

      commit('SET_TOKEN', token)
      setToken(token)

      const { roles } = await dispatch('getInfo')

      resetRouter()

      // generate accessible routes map based on roles
      const accessRoutes = await dispatch('permission/generateRoutes', roles, {
        root: true
      })

      // dynamically add accessible routes
      router.addRoutes(accessRoutes)

      // reset visited views and cached views
      dispatch('tagsView/delAllViews', null, { root: true })

      resolve()
    })
  },
  getPlaToken({commit}) {
    return getPlaToken().then(res => {
      // this.plaToken = res.data.access_token
      commit('SET_UPLOADTOKEN', res.data.access_token)
      return res
    })
  },
}

export default {
  namespaced: true,
  state,
  mutations,
  actions
}
