<template>
  <div class="menu">
    <el-menu 
      :default-active="activeIndex" 
      :default-openeds="openedIndex" 
      router 
      @select="handleSelect"
      background-color="#F9FAFB"
      active-text-color="#FFF"
      text-color="rgba(0,0,0,0.45)">
      <template v-for="meun in meuns">
        <el-menu-item class="img-menu" :key="meun.path" :index="meun.path" v-if="!meun.children && !meun.hidden">
          <span slot="title">
            <!-- <div>
              <img class="icon" :src="require(`@/assets/menu/${meun.meta.icon}.png`) " :alt="meun.meta.title">
            </div> -->
            {{ meun.meta.title }}
          </span>
        </el-menu-item>

        <el-submenu v-if="meun.children && meun.children.length && !meun.hidden"
                    :key="meun.path"
                    :index="meun.path">
          <div slot="title" class="img-menu">
            <div>
              <img class="icon" :src="require(`@/assets/menu/${meun.meta.icon}.png`) " :alt="meun.meta.title">
            </div>
            <span>{{ meun.meta.title }}</span>
          </div>
          <template v-for="(child, childeIndex) in meun.children">
            <!-- <el-submenu v-if="child.children && child.children.length && !child.hidden"
                        :key="child.path"
                        :index="child.path">
              <template slot="title">
                <i v-if="child.meta.icon" :class="child.meta.icon"></i>
                <span>123{{ child.meta.title }}</span>
              </template>
              <template v-for="(child, childeIndex) in child.children">
                <el-menu-item :key="childeIndex"
                              :index="child.path">
                  <i v-if="child.meta.icon" :class="child.meta.icon"></i>
                  <span>223{{ child.meta.title }}</span>
                </el-menu-item>
              </template>
            </el-submenu> -->
            <el-menu-item :key="childeIndex"
                          :index="child.path"
                          class="img-menu"
                          v-if="!child.hidden">
              <span>{{ child.meta.title }}</span>
            </el-menu-item>
          </template>
        </el-submenu>
      </template>
    </el-menu>
  </div>
</template>

<script>
export default {
  name: 'Menu',
  data() {
    return {
      meuns: [],
      openedIndex: ['/data'],
      activeIndex: ''
    }
  },
  watch: {
    '$route.path'(newVal, oldVal) {
      this.activeIndex = this.$route.meta.parent ? this.$route.meta.parent : newVal
      this.meuns = this.$router.options.routes[1].children
    }
  },
  created() {
    this.meuns = this.$router.options.routes[1].children
    this.activeIndex = this.$route.path
  },
  methods: {
    handleSelect(index, indexPath) {
      console.log(index);
      console.log(indexPath);
    },
  }
}
</script>

