// 查询角色信息分页
export function queryRolePage(data) {
  return request({
    url: '/hsop/role/queryRolePage',
    method: 'post',
    data
  })
}
// 查询角色信息列表
export function queryRoleList(data) {
  return request({
    url: '/hsop/role/queryRoleList',
    method: 'post',
    data
  })
}
// 增加角色
export function addRole(data) {
  return request({
    url: '/hsop/role/addRole',
    method: 'post',
    data
  })
}
// 修改角色信息
export function updateRole(data) {
  return request({
    url: '/hsop/role/updateRole',
    method: 'post',
    data
  })
}
// 删除角色
export function deleteRole(data) {
  console.log(data)
  return request({
    url: '/hsop/role/deleteRole',
    method: 'post',
    data
  })
}
