<template>
  <div class="timer inline_center">
    <p>{{hourMinSec}}</p>
    <p>{{yearMonD}} {{week}}</p>
  </div>
</template>

<script>
export default {
  name: 'Timer',
  data() {
    return {
      newDate: new Date(),
      intervalTimer: null,
    }
  },
  computed: {
    hourMinSec() {
      const h = this.newDate.getHours()
      const m = this.newDate.getMinutes()
      const s = this.newDate.getSeconds()
      const hh = String(h).length === 1 ? `0${String(h)}` : h
      const mm = String(m).length === 1 ? `0${String(m)}` : m
      const ss = String(s).length === 1 ? `0${String(s)}` : s
      return `${hh}:${mm}:${ss}`
    },
    yearMonD() {
      const yyyy = this.newDate.getFullYear()
      const m = this.newDate.getMonth() + 1
      const d = this.newDate.getDate()
      return `${yyyy}年${m}月${d}日`
    },
    week() {
      const week = this.newDate.getDay()
      let w = ''
      if (week === 0) {
        w = '日'
      }
      if (week === 1) {
        w = '一'
      }
      if (week === 2) {
        w = '二'
      }
      if (week === 3) {
        w = '三'
      }
      if (week === 4) {
        w = '四'
      }
      if (week === 5) {
        w = '五'
      }
      if (week === 6) {
        w = '六'
      }
      return `星期${w}`
    },
  },
  created() {
    this.intervalTimer = setInterval(() => {
      this.newDate = new Date()
    }, 1000)
  },
  beforeDestroy() {
    clearInterval(this.intervalTimer)
    this.intervalTimer = null
  },
}
</script>

<style lang="less">
.timer {
  background-color: #7199F9;

  p {
    line-height: 22px;
    margin: 0;

    &:first-child {
      font-size: 24px;
      color: white;
    }

    &:last-child {
      font-size: 14px;
      color: rgba(255, 255, 255, .9);
      margin-top: 12px;
    }
  }
}
</style>
