<template>
  <div class="header_person">
    <!-- <div class="person_avatar"> -->
      <el-image
        style="width: 32px; height: 32px"
        :src="require('@/assets/dashboard/head.png')"
        fit="cover">
        <div slot="placeholder">
          <i class="el-icon-loading"></i>
        </div>
        <div slot="error" class="image_failed">
          <i class="el-icon-picture-outline"></i>
        </div>
      </el-image>
    <!-- </div> -->
    <div class="person_name">{{ hsopUser.userName }}</div>
    <el-dropdown @command="handleCommand">
      <span class="el-dropdown-link">
        <div class="person_name"><i class="el-icon-arrow-down el-icon--right"></i></div>
      </span>
      <el-dropdown-menu slot="dropdown">
        <!-- <el-dropdown-item command="psninfo">个人信息</el-dropdown-item>
        <el-dropdown-item command="pwd">修改密码</el-dropdown-item> -->
        <el-dropdown-item command="logout">退出</el-dropdown-item>
      </el-dropdown-menu>
    </el-dropdown>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
export default {
  name: 'HeaderPerson',
  computed: {
    ...mapGetters(["hsopUser"])
  },
  methods: {
    handleCommand(command) {
      if (command == 'pwd') {
        this.showPwd = true
      } else if (command == 'logout') {
        // this.$router.push('/login')
        this.logout()
      } else if (command == 'psninfo') {
        this.$router.push('/user/psn-info')
      }
    },
    async logout() {
      await this.$store.dispatch('user/logout')
      this.$router.push(`/login?redirect=${this.$route.fullPath}`)
    }
  }
}
</script>

<style lang="less" scope>
.header_person {
  display: flex;
  align-items: center;
  .el-image {
    border-radius: 50%;
  }
}

.person_name {
  margin-left: 12px;
  font-size: 14px;
  // color: rgba(0,0,0,0.65);
  color: #FFF;
}

.el-dropdown-link {
  cursor: pointer;
}

